/**
 * Point 8 — Site furniture (about, contact, compliance pages)
 * Bucket A: Verify furniture pages are present; run xlsx-to-pipeline.mjs.
 *
 * Furniture pages are generated by initialise-site.mjs Phase 1 from
 * templates/furniture/<family>/. Point 8 verifies they exist and populates
 * pipeline.json from the keyword xlsx if pipeline is still empty.
 */

import { existsSync } from 'fs'
import { join } from 'path'
import { homedir } from 'os'

export const POINT_ID = '8'
export const BUCKET = 'A'

const REQUIRED_FURNITURE = [
  'about.astro',
  'contact.astro',
  'affiliate-disclosure.astro',
  'privacy-policy.astro',
]

export async function run(ctx) {
  const { slug, platformDir, dryRun, log, execTool, state } = ctx
  const siteDir = join(homedir(), slug)
  const pagesDir = join(siteDir, 'src', 'pages')

  // Verify furniture pages exist
  log.info('Verifying furniture pages…')
  if (!dryRun) {
    const missing = REQUIRED_FURNITURE.filter(f => !existsSync(join(pagesDir, f)))
    if (missing.length > 0) {
      return { status: 'fail', message: `Missing furniture pages: ${missing.join(', ')}` }
    }
    log.info(`All ${REQUIRED_FURNITURE.length} required furniture pages present`)
  } else {
    log.info('(dry-run) would verify furniture pages')
  }

  // Populate pipeline.json from xlsx if still empty
  const pipelinePath = join(siteDir, 'data', 'pipeline.json')
  const xlsxPath = state.inputs?.keyword_xlsx_path

  log.info('Checking pipeline.json…')
  if (!dryRun) {
    let articleCount = 0
    try {
      const { createRequire } = await import('module')
      const req = createRequire(import.meta.url)
      const pipeline = req(pipelinePath)
      articleCount = pipeline?.articles?.length ?? 0
    } catch { /* pipeline.json missing or malformed */ }

    if (articleCount === 0) {
      if (!xlsxPath) {
        return { status: 'fail', message: 'pipeline.json is empty and no --xlsx path provided. Pass --xlsx to populate it.' }
      }
      log.info(`pipeline.json empty — running xlsx-to-pipeline.mjs…`)
      const xlsxTool = join(platformDir, 'tools', 'xlsx-to-pipeline.mjs')
      const r = execTool(`node "${xlsxTool}" --input "${xlsxPath}" --output "${pipelinePath}"`)
      if (!r.ok) {
        return { status: 'fail', message: `xlsx-to-pipeline failed: ${r.stderr.slice(0, 200)}` }
      }
      // Re-read count
      try {
        delete require?.cache?.[pipelinePath]
      } catch { /* */ }
      const pipeline2 = JSON.parse((await import('fs')).readFileSync(pipelinePath, 'utf-8'))
      const newCount = pipeline2?.articles?.length ?? 0
      if (newCount === 0) {
        return { status: 'fail', message: 'xlsx-to-pipeline ran but pipeline.json still empty' }
      }
      log.info(`pipeline.json populated: ${newCount} articles`)
    } else {
      log.info(`pipeline.json already populated: ${articleCount} articles`)
    }
  } else {
    log.info('(dry-run) would run xlsx-to-pipeline.mjs if pipeline empty')
  }

  return { status: 'pass', logFields: { furniture: 'verified', pipeline: 'populated' } }
}
